package com.andye.warmod.radar.station.client;import com.andye.warmod.warhead.client.render.WarheadRenderPipelines;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.renderer.SubmitNodeCollector;public final class RadarDishRenderer {private RadarDishRenderer(){}public static void submit(RadarStationRenderState s,PoseStack pose,SubmitNodeCollector collector){pose.pushPose();pose.translate(.5,1.72,.5);pose.mulPose(Axis.YP.rotationDegrees((float)s.sweepAngle));pose.mulPose(Axis.XP.rotationDegrees(-18));collector.submitCustomGeometry(pose,WarheadRenderPipelines.PROJECTILE,(p,b)->RadarDishMesh.render(p,b,s.lightCoords,s.warningActive));pose.popPose();}}